quests[50876] = { id = 50876, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Murderbeak" }
quests[50877] = { id = 50877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gahz'ralka" }
quests[50878] = { id = 50878, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blurred Vision", description = "Look up.\n\nSee them, scattered among the trees? Those brightly glowing owls are not living, breathing denizens of the forest... they are Kaldorei magic. Sentries. A ruse -- reporting everything they see back to Malfurion.\n\nWe can't have that, now can we?\n\nDeal with them, {name}. But take care -- they aren't the only enemies in the forest.\n\nWe cannot allow anything or anyone to stand in our way.", completion = "Nicely done.", objectives = "Eliminate the Sentry Owls in the trees and slay the frenzied furbolg of Darkshore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50879] = { id = 50879, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Trees Have Ears", description = "With the eyes of the forest shut, one thing remains: the ears. Ancients. \n\nThey feel the vibrations of our footsteps and report our every move to Malfurion.\n\nGot that torch handy?", progress = "These Ancients must be taken care of.", completion = "Come, Champion. Let us take this ancient grove.", objectives = "Defeat the Burning Ancient.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50880] = { id = 50880, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Unstoppable Force", description = "Now is the time to strike, {name}. \n\nPassing through the wall will not be easy, but I think it's something you can handle. Do what you must to prevail, and meet me on the other side. I will lead a squad of sturdy soldiers and as many demolishers as can survive the passing.\n\nWe may not make it to Darnassus today, but the outcome of this war does not rest on one victory alone -- it will come as the result of a thousand small victories.\n\nSo let's get started, shall we?", completion = "Malfurion will return with his forces, but until then let's press on.", objectives = "Disrupt the Alliance forces in Darkshore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50881] = { id = 50881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Royal Report", description = "Blood magics practiced in de city, guards missing, and our chief spy, Yazma, is acting suspicious. We must present dis to Rastakhan, but without Yazma interfering.\n\nLuckily, Rastakhan is a clever king, which is something his opponents often forget.\n\nI have prepared a report in a code made by King Rastakhan and known only to myself and my brother, Habutu. Bring it to Habutu and he will see dat it gets to de king's ear.", completion = "Hmm. Zolani speaks highly of your deeds. Perhaps we may not need to kill you yet.", objectives = "Deliver Zolani's report to Habutu at the Golden Throne.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50882] = { id = 50882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All to Ash", description = "All throughout our campaign here, I understood the warchief's objective. I saw her strategy... believed in its necessity.\n\nWith Darnassus in Horde hands, the Alliance would be paralyzed. Anger and fear would fester in their hearts until they cracked and splintered like deadwood.\n\nBut this... this will unite them. They will come for us. All of them.\n\nReturn to the Undercity, {name}. Speak to the warchief. We must make ready for what is to come.", sourceObjective = "Speak to Warchief Sylvanas Windrunner in Undercity.", sourceObjectiveStatus = "unverified-source-field" }
quests[50885] = { id = 50885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lei-zhi" }
quests[50886] = { id = 50886, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Surrogate Wings", description = "It is not my way to coddle the young of my brood. But I think I will make an exception for your little one.\n\nAfter all, I have seen you tend to him. It would be cruel to let your... efforts... go to waste.\n\nVenture into Zuldazar city proper and find something that can act as a surrogate wing for your young one.\n\nWingminder Goja will know what to do next. Speak to him once you have it.", progress = "Did Pa'ku offer any useful advice?", completion = "What is this?\n\n<Wingminder Goja looks between you and the pterrordax and grins.>\n\nOh, I get it!", objectives = "Acquire a Huge Dragon Kite.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50887] = { id = 50887, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ptrust Fall", description = "I just want you to know how unusual this is for Pa'ku. She prefers to teach on the fly.\n\nWhat? It's true.\n\nThis method might work. Sometimes when young pterrordax are not eager to fly, their mother will drag them from the nest and hold them in her claws until they are comfortable enough to spread their wings.\n\nSeeing as this little one has no mother, you will use the kite to act as one.\n\nPa'ku has placed a trail for you to follow.\n\nGo and glide carefully- you may frighten your pterrordax more!", completion = "<Pa'ku eyes your hatchling sourly.>\n\nAre you sure we can't just throw him next time?", objectives = "Board the Huge Dragon Kite and take your pterrordax on a flight to build his confidence.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50897] = { id = 50897, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turn the Heat Around", description = "<In standard goblin fashion, the Horde forces seem to be using flamethrowers to clear out the snow.>\n\n<This one is still usable despite being beaten on, you could use it to destroy some of the goblin mining machinery.>", completion = "<Oh, the sweet sound of goblin-made explosions.>", objectives = "Destroy 6 pieces of goblin machinery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50899] = { id = 50899, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Don't Stalk Me, Troll" }
quests[50900] = { id = 50900, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maybe When You're Older", description = "<Pa'ku squints down at the young pterrordax.>\n\nWell, I am out of ideas. My son will take you back to the nest. Do not worry, this one can fly.\n\nYOUR little one will need to get back on his own. It builds character.\n\nMaybe he will grow out of this absurd deficiency in time.", progress = "How did it go?", completion = "Pa'ku is Lord of Wind. Naturally she expects young of her brood to take the same joy in flight.\n\nYour little one will come around. Some just take longer than others.", objectives = "Return to the nest at Pterror Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50901] = { id = 50901, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saurid Surprise", description = "Da sands of Vol'dun be full of harsh creatures, but none so harsh as dey dat da Zandalari send.\n\nOne of dese criminals be right here in da Scorched Sands. His name be Sezahjin, and he be da former chef ta da king. Did he tell ya dat he be famous for a dish called \"Saurid Surprise?\" Guess what da main ingredient be.\n\nHe be fallin' far, but not far enough for Jani. It be time ta take his pride.\n\nJust be makin' sure dat da creatures of da sand not be seein' ya.", progress = "Ya taken dat accursed chef's hat yet, richmon?", completion = "Haha! Well done, richmon. No doubt he gonna find another hat eventually, but you took da one he be wearin' when he cook up his Saurid Surprise. Ya have earned me favor.", objectives = "Survive Jani's prank on Sezahjin.\n\nIf you lose your saurid disguise, return to Jani for another.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50903] = { id = 50903, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Missing Master", description = "Master Ashton had me grab some healing supplies and run to Mayor Royston when those things attacked town. He didn't make it behind the barricade.\n\nBut if he's alive--and he's just crazy enough he might be--he's probably holed up in his cottage. With caustic compounds. And explosives.\n\nLook, why don't you go check out his basement and I'll stay out of the blast radi- I mean I'll go see if the garden can be salvaged.\n\nTry not to look flammable.", progress = "Oh! You're not one of those monsters at all. Did you trounce those brutes?", completion = "I appreciate your help in liberating the town! I was becoming quite concerned by these strange monsters.", objectives = "Find Master Ashton.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50904] = { id = 50904, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Abandoned Passage", description = "My people have known about this ancient passageway for generations, but none have dared enter before now.\n\nThe tunnel leads to the tomb of Mythrax the Unraveler and it is said that his power still radiates within the cavern. Who knows what horrors await us inside...\n\nIt appears that your friends have already gone inside to face Jakra'zet and stop him from raising Mythrax from the dead.\n\nWe don't have time to waste. We must find Kaja and Rakera before they confront Jakra'zet on their own!", completion = "Jakra'zet has already begun the ritual. We must stop him before it's too late!", objectives = "Find Bladeguard Kaja and Warguard Rakera in Atul'Aman.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50908] = { id = 50908, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smells Like Trouble", description = "The Horde spilled a lot of blood in Brennadam. Now it's time to spill some more.\n\nThe scent of blood makes predators in these hills go crazy. We use it to lure animals when hunting.  \n\nThe Horde forces are occupying caves up in the hills. Toss these scent vials into the caves where the Force Commanders organize the attack. The smell should bring all the hills down upon them!", progress = "Those scent vials should help you eliminate both Force Commanders.", completion = "With you around, they won't try this again.", objectives = "Slay Force Commanders Ogarth and Durmok.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50909] = { id = 50909, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Never Outgunned", description = "This is our new home now, and we will fight to keep it!\n\nWe may be outnumbered here, but we aren't going to be outgunned.\n\nFind us every axe, sword, spear, crossbow, and gun for our rebellion!", progress = "We'll need more than that. Find us some weapons!", completion = "This is a good start.", objectives = "Find us 15 Rebel Weapons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50910] = { id = 50910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dangerous Game", description = "Most of these Horde don't scare us, but we lost two people today to a group of forsaken keenblades. We've had trouble tracking them down, we could really use your help.\n\nThey're stealthy and dangerous fighters, so show no mercy.", completion = "Your skills are impressive.  I don't think any of us could have taken out those keenblades so easily.", objectives = "Rid the hills of these Forsaken Keenblades.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50911] = { id = 50911, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Man Against the Horde", description = "Me an' a few friends were trying to help some of the folks from Corlain flee safely to Arom's Stand after things started gettin' weird. I noticed some movement up the hill so I decided to come back and check it out. If the town goin' mad wasn't bad enough, now we have another problem to deal with.\n\nThe Horde.\n\n<McKellis spits.>\n\nThose fools have no place on our lands. Wash the snow with their blood.", completion = "The only good orc is a dead orc.", objectives = "Kill 10 Horde forces.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50912] = { id = 50912, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Remix to Ignition", description = "<A goblin mining machine is halfway sticking out of the snow.\n\nDespite being buried, it seems to be in working condition. If only you had a key.>", progress = "<The machine lays lifeless on the snow.>", completion = "<With a bit of effort, you free the machine from the snow. It whirs to life upon using the key.>", objectives = "Find the ignition key.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50913] = { id = 50913, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Akunda's Blessing", description = "You have proven worthy of my blessing, {name}.\n\nThis means should you choose me as your loa, you can call upon my power when needed.\n\nCommune at my shrine to receive my gift.\n\nKnow that whatever you choose, you will always be welcome within these walls.", progress = "I bestow my blessing upon my followers.", completion = "If at any time you require my gift, commune at a shrine built in my honor to receive my boon.", objectives = "Commune at Akunda's Shrine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50929] = { id = 50929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Powder to the People", description = "The Horde filth up on that hill seem to be mining some kind of ore I've not seen before.\n\nIf they've come all the way out here to find it, it must be valuable. Take what you can find!", progress = "Did you figure out what they were doing up there?", completion = "This just looks like a pile of junk!", objectives = "Gather Azerite from 6 crates.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50930] = { id = 50930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Falling With Style", description = "<Kua'fon looks to the kite, then back at you. He looks to the kite again, poking his head forward deliberately. He slowly pans his gaze back to you.>\n\nSkree.\n\n<Time for another flight!>", progress = "There is a method to Pa'ku's madness.", completion = "Another successful flight! I only hope it helps Kua'fon learn that de sky is his home, in time.\n\nDo not worry, he will get back up to de nest on his own.", objectives = "Take Kua'fon on another flight on the Huge Dragon Kite.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50933] = { id = 50933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Unfortunate Event", description = "<You have no means of identifying the corpse, but the clothing appears to be that of an imperial guard from Zuldazar.\n\nA quick search of the area reveals a trail of blood that heads off to the west. Perhaps if you follow it you can discover the cause of death.>", completion = "You do not look like one of de prisoners. I... I could use your help.", objectives = "Discover what happened to the Imperial Guard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50934] = { id = 50934, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Chance Sighting", description = "One of the lookouts said he saw a bunch of blood trolls chasing after a Zandalari on the other side of the river.\n\nHe seemed to be dressed like your group. Why do you people keep running into trouble in this place?\n\nI'll mark on your map where he was last seen. Just don't bring a horde of blood trolls over here, alright?", completion = "<The Zandalari next to this antidote is barely alive.>", objectives = "Investigate the missing Zandalari.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50936] = { id = 50936, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Survival Strategy" }
quests[50940] = { id = 50940, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wisdom of the Wingless", description = "<Kua'fon wheezes and quivers, exhausted.>\n\nIt's not going anywhere. Maybe it's time to seek someone without wings for advice.", completion = "I heard de screeching. Glad to see you still be in one piece.", objectives = "Seek out Hexlord Raal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50942] = { id = 50942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dress for the Slide, Not the Ride", description = "If Kua'fon is serious about flying, we're going to need to protect him.\n\nGo get a berserker skull and some armor for it. Meet me down in Talanji's Rebuke and we'll get him dressed for success.", progress = "You got the things I asked for?", completion = "Now, perhaps, your companion will not be afraid of his next fall. Haha!", objectives = "Collect a Berserker Skull and Lightweight Skyterror Barding.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50943] = { id = 50943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Joy of Flight", description = "You be ready, {name}?\n\nKua'fon is ready to fly. Whether or not he can is another question, but all the same I will see you two back to the roost.\n\nClimb aboard and guide him. I can't imagine he can see very well through that skull.\n\nAta and I will lead the way.", completion = "<Kua'fon pants from exertion, but he seems content with his efforts.>\n\nSkree.", objectives = "Follow Hexlord Raal and fly Kua'fon back to the roost", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50944] = { id = 50944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down, But Not Out", description = "<Kua'fon wiggles happily in his new armor. He starts to pace restlessly back and forth. A taste for adventure has surely awakened in this flightless creature.>\n\nSkree! Skree!!", completion = "<Kua'fon lowers its head and gently nuzzles you. He is ready to follow you wherever you may go.>", objectives = "Accept Kua'fon as your new traveling companion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50953] = { id = 50953, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Greenstalker", description = "The mighty wolf Greenstalker was once a protector of these forests. He has fallen under the sway of dark forces. My brother and I attempted to calm his spirit, but he is too far gone.\n\nUse the charm I have constructed to weaken him. I ask you {class}, please, end his suffering.\n\nMy brother is still weak and I must stay to protect him. Go now before the wolf consumes us all!", progress = "Did you free Greenstalker's spirit?", completion = "A grim but necessary task. I hope Greenstalker's spirit will find peace now.\n\nBe careful, {name}. These woods are being twisted by ancient power.", objectives = "Slay Greenstalker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50954] = { id = 50954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zandalar Forever!", description = "Bwonsamdi has whispered a warning to me: the enemy is on the move.\n\nI have gathered what defenses I could in the time allowed but we are dangerously under powered. \n\nI can only hope that, thanks to your efforts, the loa will be with us this day.\n\nAre you ready to defend Zandalar?", completion = "We have won the battle, not the war.", objectives = "Complete the Zandalar Forever scenario.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50955] = { id = 50955, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We're Not Friends", description = "I did some time in Tol Dagor with the captain of this crew, Calico McGee. He likes to hang back and direct his men from afar.\n\nI just happened to have spotted him across the flats. You and I should go pay him a visit!", completion = "I never liked his cat.", objectives = "Eliminate Calico McGee.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50956] = { id = 50956, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Walking-Around Money", description = "This is a lot of gold! It's gonna take me a while to split this up. I can give you some walking-around money to hold you over until I am done.\n\nCome back tomorrow, maybe I will have it figured out.", completion = "<A small advance from Leo, against my share of the loot.>", objectives = "Accept the money.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50957] = { id = 50957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrath of Rezan" }
quests[50958] = { id = 50958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Watch Your Wallets" }
quests[50959] = { id = 50959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plundering Pirates" }
quests[50960] = { id = 50960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sweete's Orders", description = "<Tucked into the pages of the captain's logbook is a letter bearing the seal of Harlon Sweete.\n\nIt looks like these pirates have been ordered by Sweete to cause further disruption to House Waycrest. \n\nLucille should be notified of this immediately!>", progress = "What have you brought, mainlander?", completion = "<Lucille reads the orders.>\n\nSo This pirate seeks to destabilize House Waycrest? As if we don't have enough problems already!\n\nThank you for bringing this to my attention, {class}. It seems that the coven might just be the beginning of Kul Tiras' troubles...", objectives = "Bring Sweete's Orders to Lucille Waycrest in Drustvar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50961] = { id = 50961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Save Our Scrolls!" }
quests[50962] = { id = 50962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cargo Reclamation" }
quests[50963] = { id = 50963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Of Dark Deeds and Dark Days", description = "I should have known better, and now Rezan is dead, and my own power is barely holding on. Soon Bwonsamdi himself will be coming to collect me.\n\nTalanji... she must know what has happened here. Go to her, tell her. Aid her where you can.\n\nI followed a god of strength and yet I have not de strength to face her with dis shame.\n\nFor now, I must gather our forces and pursue Zul.", completion = "Rezan is... dead?", objectives = "Speak with Princess Talanji in the Royal Chambers of Dazar'alor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50964] = { id = 50964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritual Combat" }
quests[50965] = { id = 50965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Those Who Remain", description = "<The runes on the wooden plaque glow faintly with an ancient magic. It looks like it is a small piece of a larger record.>\n\n<One of the Thornspeakers at the Teller Farm would probably recognize what this is.>", progress = "Is there something more you need?", completion = "These are a few of the remaining relics of my kin. I thought them lost. You have my utmost gratitude.", objectives = "Collect 8 Ashenwood Relics.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50966] = { id = 50966, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleanup Crew" }
quests[50967] = { id = 50967, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost in the Woods", description = "My student, Amalie, and I have taken it upon ourselves to act as the keepers of these woods. We were away from Drustvar briefly, and upon our return, found the grove infested and the surrounding land corrupted.\n\nAmalie decided that she could deal with the grove infestation alone.\n\nIt's been some time since she ran off, could you look for her while you're in the Ashenwood?", completion = "She said she would head back on her own? At least she is safe.", objectives = "Find Amalie Oakseeker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50969] = { id = 50969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emergency Management" }
quests[50970] = { id = 50970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Farmer's Fate", description = "Old Jakob here was one of the few folks who were never wary of us. I have, on occasion, even helped him around his farm in return for supplies. It is an injustice just to ignore his plight even amidst our own problems.\n\nThe corruption which holds him seems to be early in form. I believe I can cleanse it.\n\nTake this branch, and bring it to the three shrines around the Ashenwood. That should allow it to gather enough energy for the ritual.", completion = "The wood remembers, and guides us. This should be enough power to help this farmer.", objectives = "Empower the Everliving Branch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50972] = { id = 50972, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proudmoore's Parley", description = "So, we meet again.\n\nI... apologize for how you were treated last time. I trusted Priscilla like a sister and-- \n\n<Katherine chokes up for a moment before regaining her composure.>\n\nLet us keep this brief, for I will make no promises nor any formal accords in this state.\n\nReturn to your leaders. Tell them I wish to parley.\n\nThat is all for now. My people have suffered a great deal today and I have much to reflect upon.", completion = "So, Katherine is willing to speak with us at last?\n\nWell done.", objectives = "Report to Genn Greymane in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50973] = { id = 50973, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Heart's Power", description = "The world's soul grows stronger, {name}, but there's still trouble out there. Azerite surges from her wounds, and all sides fight tae claim its might.\n\nYe have proven yerself tae be Azeroth's champion. And thanks tae all ye have done, I sense a great power stirrin' in that amulet ye wear.\n\nAzeroth calls tae us. She wants me tae help ye unlock even greater strength in her Heart. Are ye ready?", progress = "Hold still, champion, while I empower the Heart of Azeroth.", completion = "Can ye feel it, {name}? The Heart of Azeroth grows stronger!\n\nI believe we can unlock even more o' that amulet's potential.\n\nYou keep on absorbin' all the Azerite ye find, and I'll search for some way tae bring this madness tae an end.", objectives = "Ask Magni Bronzebeard to empower the Heart of Azeroth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50975] = { id = 50975, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azerite Mining" }
quests[50976] = { id = 50976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Ancient Curse", description = "<The harsh conditions of Nazmir have not been kind to the stone tablet.\n\nMost of the inscriptions have been worn away but you are able to make out a picture that shows a chest surrounded by glyphs. Above the chest you noticed what appears to be a large floating skull.\n\nBelow the images you find a single word \"Aiji\".\n\nThe ruins ahead seem foreboding, and you may want to bring some friends to help you.\nWith their help, perhaps you can find the secret of this \"Aiji\" and its treasure within.>", objectives = "Activate the braziers of Xal'vor and defeat Aiji the Accursed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50977] = { id = 50977, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smuggler Shakedown" }
quests[50978] = { id = 50978, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out With the Old Boss", description = "Right so I talked to some people. You talked to some people. No one likes the Irontide. They're cutting in to profits and scaring off good, honest scoundrel- er customers! \n\nWe take out the guy in charge and we'll be able to run the rest outta town! So a little change of management is in order.\n\nI'm not usually one for stabbin' people, I'm a lover not a fighter, but I can pay. You do this for me and I'll make sure you're welcome here whenever ya want? Sound good?", completion = "Great! I'm the Boss of the Cove now and what I say goes.\n\nSince you've been a pal, I'll let you stop in whenever you like. Remember to bring gold.", objectives = "Slay Richard Tornsail.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50979] = { id = 50979, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just a Nip", description = "My tough-guys-in-training are quick learners! \n\nThey do seem to get a bit... bitey... when they're grouchy, though. Too many, and I start to get a little light-headed.\n\nThe nearby atrivax plants have a medicinal gel. It is great to treat fresh wounds and nullify venom.\n\nThey don't like sharing it. Could you harvest a bit for me?", progress = "How goes the juicing?", completion = "Thanks, {name}! That should do the trick!\n\nAt least it will tide me over until they realize we're on the same side.", objectives = "Get 10 samples of Atrivax Gel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50980] = { id = 50980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Hungry Neighbor", description = "There is an angry hydra that has decided to make a nearby ridge his home.\n\nHe keeps getting bigger, and meaner, and hungrier!\n\nMy cobras are terrified. \n\nPlease, {name}, take care of him before he comes after us!", completion = "It seems he found you indigestible. Excellent work!\n\nWe all thank you!", objectives = "Kill the Territorial Hydra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50981] = { id = 50981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work Order: Riverbud", progress = "Are you here to deliver supplies?", completion = "Thank you for assisting us, herbalist. We needed this riverbud badly." }
quests[50982] = { id = 50982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work Order: Star Moss", progress = "Are you here to deliver supplies?", completion = "Thank you for assisting us, herbalist. We needed this star moss badly." }
quests[50983] = { id = 50983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work Order: Akunda's Bite", progress = "Are you here to deliver supplies?", completion = "Thank you for assisting us, herbalist. We needed this akunda's bite badly." }
quests[50984] = { id = 50984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work Order: Winter's Kiss", progress = "Are you here to deliver supplies?", completion = "Thank you for assisting us, herbalist. We needed this winter's kiss badly." }
quests[50985] = { id = 50985, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work Order: Siren's Pollen", progress = "Are you here to deliver supplies?", completion = "Thank you for assisting us, herbalist. We needed this siren's pollen badly." }
quests[50986] = { id = 50986, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work Order: Sea Stalk", progress = "Are you here to deliver supplies?", completion = "Thank you for assisting us, herbalist. We needed this sea stalk badly." }
quests[50987] = { id = 50987, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work Order: Monelite Ore", progress = "Are you here to deliver supplies?", completion = "Thank you for assisting us, miner. We needed this monelite ore badly." }
quests[50988] = { id = 50988, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Economic Opportunity", description = "You look savvy enough to jump on an opportunity when one comes by and, pal, do I have one for you.\n\nSee that cove down there? It's run by entrepreneurs with an eye towards meeting the logistical shortfalls that might come up in your typical city or town situation. Well, it's normally run by them.\n\nWe have a bit of an infestation by folks who are more mercenary minded if you catch my meaning.\n\nYou help me win back control of the cove and I'll see you're treated well. Sound good?", completion = "Right! So. Cards on the table. We're smugglers. We're not pirates. Everyone wants those red-coated jerks gone.\n\nYou help me become boss of Anyport and I'll help you.\n\nTalk to some of the key folks around here. Do some favors for 'em then come back to me, got it?", objectives = "Meet Cesi Loosecannon inside Anyport.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50989] = { id = 50989, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work Order: Storm Silver Ore", progress = "Are you here to deliver supplies?", completion = "Thank you for assisting us, miner. We needed this storm silver ore badly." }
quests[50990] = { id = 50990, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cutting Edge Poultry Science", description = "<Before you is a delicious chicken... And yet, despite everything, there is something a little bit... lively about this creature.\n\nWith a judicious application of science, there might be something that can still be done for this poor bird.\n\nYou resolve to bring the chicken to Dr. Oglethorpe in Booty Bay with all haste.>", completion = "Hmm, a difficult case but I believe I can help!\n\nThese days so many people concerned if science should do something rather than if science can do it! Now let's see... Some wire, a few gears, a bit of feath-growth potion and some good old rocket fuel for some kick... And presto! One robotic chicken back from the brink!\n\nEr, if it goes insane and tries to kill everyone, you were never here and we never had this conversation.", objectives = "Take the Delicious Chicken to Dr. Oglethorpe in Booty Bay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50991] = { id = 50991, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work Order: Blood-Stained Bone", progress = "Are you here to deliver supplies?", completion = "Thank you for assisting us, skinner. We needed these blood-stained bones badly." }
