quests[51001] = { id = 51001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Every Day I'm Smugglin'", description = "Hey! Wanna make some quick gold?\n\nSee, I had a mishap a few weeks ago with a shipment. Too much grog, dark seas, sudden rocks. You know, that old story.\n\nAnyway, my cargo's been floating out there and no one will get it back for me. Can you believe it? You bring my cargo back and I'll pay you a generous recovery fee.\n\nWe got a deal? Great!\n\nOh, uh, watch out for the sharks. Did I forget to mention the sharks?", progress = "You get the goods?", completion = "Hey thanks! Bit damp but still good.", objectives = "Collect 5 Smuggled Goods from the sea near the shipwreck close to Anyport.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
