quests[51015] = { id = 51015, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work Order: Deep Sea Satin", progress = "Are you here to deliver supplies?", completion = "Thank you for assisting us, tailor. We needed this deep sea satin badly." }
quests[51016] = { id = 51016, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeking More Knowledge", description = "It pains me to admit that I don't know everything about plants.  I've taught you everything I know about Anchor Weed, but I think I know where you could look to learn more.  Unfortunately, it's in Waycrest Manor, and that whole area's been crawling with monsters as of late.\n\nIf you find yourself inside that manor, keep an eye out for a book called, \"The Treatise on Anchor Weed\".  Its author spent decades studying that forsaken weed.", progress = "Have you retrieved the book?", completion = "Outstanding! And it's in such good condition, too! Now let's see if there's anything in here that could be of help for you.\n\n<Several moments pass as Declan mutters to himself excitedly>\n\nAh ha! Here ya go! The seed pods open when the plant is disturbed, but if the first cut is at the base, that drains a reservoir of water that is used to open and close the pods.  So, start at the bottom, working your way up, and you should get a better harvest.", objectives = "Retrieve the Treatise on Anchor Weed from within Waycrest Manor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51017] = { id = 51017, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supplies Needed: Monelite Ore", progress = "Are you here to deliver supplies?", completion = "Thank you for assisting us, {class}. We needed this monelite ore badly." }
quests[51018] = { id = 51018, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Asking for a Friend", description = "Hey! Since you helped Cesi I thought maybe you might do a favor for me.\n\nWell, uh, y'see Miss Sweetflower over there? Sweet as honey, sharp as a tack, and cooks like a goddess.\n\nI'm not much to look at, but the lady might think kindly on me if I could surprise her with a gift. A really great gift! But I can't leave m'post or these red-coated jerks might run off with the merchandise. \n\nThis is where you come in. Find out what Miss Sweetflower wants, get it and bring it back to me.", progress = "Did you find something?", completion = "She wanted this?\n\n<Kane cracks open the jar slightly. His eyes begin to water immediately.>\n\nT-thanks.\n\n<Coughing, Kane hastily re-seals the jar.>\n\nThat must have cost a lot. Let me pay you back with a tip.", objectives = "Ask Xun Xun Sweetflower what she would like and acquire it in Anyport.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51019] = { id = 51019, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "She's Got it Where it Counts", description = "Word is you're looking to drum up support for Loosecannon. Well I'll buy in if you help me. They took my poor Miranda! \n\nBoss Tornsail says I had too much to drink and bet her in cards. I don't really remember what happened last night, but I can hold my liquor and I'd never bet my bird! I suspect funny business. She might not look like much, but Miranda's the fastest damn falcon you'll ever see.\n\nThey're watching me, so you go free her. She'll fly someplace safe and I'll get her later. We got a deal?", completion = "Ha! Did you see her fly out of there? Like the wind!\n\nThank you, {name}. You and Cesi can count on my support.", objectives = "Free Miranda the falcon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51020] = { id = 51020, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cutthroat Business Practices", description = "I used to run the inn here. Was a nice gig. I got first crack a lot of good stuff and all the best gossip and information came through my place.\n\nAnd then that jerk, Gary Cofferdam, came in and kicked me out! The new Boss laughed! \n\nI'm lookin' at my last few silvers here. Business is not good!\n\nTell ya what, you remove my problem and I'll side up with Cesi. She'd never kick me out.", completion = "Looks like this port needs a new innkeeper.\n\nA pleasure doin' business with ya, {name}", objectives = "Slay Gary Cofferdam in Anyport.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
