quests[51053] = { id = 51053, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Day the Port Fell", progress = "I've witnessed countless horrors through countless generations.", completion = "Dat was where it all began. I could've stopped Zem'lan right dere... I could've prevented dis fate for de crew.\n\nInstead, I led dem straight into it.", objectives = "Use First Mate Jamboya's Medallion to view a vision of his past.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51054] = { id = 51054, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Overdue Mutiny", completion = "Dis won't be easy, {name}. But it be worth it.", objectives = "Free First Mate Jamboya.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51055] = { id = 51055, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Yard Arm of the Law", description = "I'm not de only pirate Zem'lan has had strung up around de port. Hangin' on de yard arm is his favorite form of punishment for de crew.\n\nWe can't feel pain and don't stay dead, so his options are limited.\n\nLook for more crewmates hangin' around town. Tell dem to meet me here after you free dem.\n\nAfter weeks of hanging helplessly while being mocked and abused by de rest of de crew, I bet dey be willin' to discuss mutiny.", completion = "It looks like we all be of one accord. It be mutiny!", objectives = "Free Quartermaster Tulmac, Gunner Bosanya, and Jukanga the Snitch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51056] = { id = 51056, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Last Day Alive", description = "De curse came one fateful day, in ages past, when de sethrak attacked. Dere was no end to dem.\n\nIn our desperation, I helped Pirate-King Zem'lan do de unthinkable.\n\nWe became monsters. Even worse, we became eternal slaves to Zem'lan.\n\nDe curse weighs heavy on me, but my guilt is heavier. I led me crew into dis.\n\nBefore we confront de Pirate-King himself, you need to understand what we be up against.\n\nYou need to see what happened de day dat de Port of Zem'lan fell.", completion = "Now you know how desperate we were on dat day, {name}.\n\nI don't be making excuses, but you should understand why we did what we did.", objectives = "Use First Mate Jamboya's Medallion to witness visions of his past.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51057] = { id = 51057, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maroon 'em with Fire", description = "We gonna have to sail out to de Golden Isle to face Pirate-King Zem'lan.\n\nLet's make sure de rest of de crew can't follow us once we go. Burn their boats in de harbor.", progress = "Don't burn my boat, {name}. We be needin' dat one.", completion = "Good. We be ready to sail.", objectives = "Use the Undying Torch to burn 8 Pillaging Canoes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51059] = { id = 51059, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Golden Isle", description = "Pirate-King Zem'lan don't stay in de port with de rest of us. Too good to crack a jug with his crew no more.\n\nWe gotta sail out to de Golden Isle to find him. That be de forbidden island where Zem'lan hoards all of de treasure we've pillaged and plundered, so only he can enjoy dem.\n\nHop in my boat and we'll row out dere together.", completion = "Here we are. De Golden Isle. It's beautiful, ain't it?\n\nA pirate's paradise.", objectives = "Ride in Jamboya's boat out to the Golden Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51060] = { id = 51060, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our Share of the Plunder", description = "Dis treasure belongs to de crew! We've fought every battle for Zem'lan, but he hoards all de booty for himself.\n\nAnd if ya try to take some for yourself, he turns ya into one of his goldslaves. Those be de mindless drones ya see tendin' to de treasure out here.\n\nWe ain't leavin' here empty-handed after de mutiny. Collect all de treasure ya can!\n\nBeware de cursed bits. It don't hurt us, but I'm guessin' it'll hurt you.", progress = "More treasure!", completion = "I suppose dis little amount of gold won't be cursin' ya for too long. I'll carry de rest.", objectives = "Collect 12 Cursed Treasures of Zem'lan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51061] = { id = 51061, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The First Time I Died", description = "Dis be it. Where Zem'lan cursed us all.\n\nIt began with me death. De first of countless deaths I've had since. Each of dem spent fighting and dying for Pirate-King Zem'lan and his selfish treasure hoard.\n\nI don't know if de idols he used to curse us can even be destroyed, but we gotta try. Let's take dem to de altar where de ritual occurred and try to smash one.", completion = "I guess de idols can't be destroyed... even by a mortal. Curses be fickle things.\n\nI was de first Zem'lan cursed, and I did nothin' to stop him from cursin' de rest of de crew.\n\nI regret it every day...\n\nBut enough livin' in de past. It's time to be free.", objectives = "Place the idols on the altar and try to destroy them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51062] = { id = 51062, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Escaping Zem'lan", description = "Pirate-King Zem'lan was right about one thing: he won't stay dead for long.\n\nWe gotta take our treasure and get out of here while we got de chance.\n\nWe can take de boat, but we'll need a place to hide out for awhile. Are your vulpera friends open to housin' a few stowaways?\n\n<First Mate Jamboya motions to the piles of treasure in his boat.>\n\nClearly, we can pay dem for their trouble.", completion = "What have you gotten us into, {name}? We asked you to find our friend, not bring monsters into our camp.", objectives = "Ride Jamboya's boat to the shore and lead the pirates to Camp Lastwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51064] = { id = 51064, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azerite Wounds" }
quests[51068] = { id = 51068, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raiding Their Stores", description = "We're low on food supplies.\n\nHit up Newstead and bring us whatever you can find.You will be able to choose one of these rewards:", objectives = "Obtain a Roast Boar, a Colossal Cheese Wheel, a Basket of Eggs, and a Keg of Applebrew.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51069] = { id = 51069, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Darkspeaker Jo'la", description = "Wanted for atrocious crimes against the Zandalari: Darkspeaker Jo'la\n\n Defeat this powerful adherent of Zul, and a great reward shall be yours.", completion = "Dat troll was nothing but bad news for everyone. You have done well.", objectives = "Slay Darkspeaker Jo'la", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51070] = { id = 51070, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raiding the Boulderfist", description = "The Boulderfist have recently raided Drywhisker Mine, and are sitting on a large amount of iron ore.\n\nWe want it back.", progress = "We can't let the Alliance take Arathi. We'll use whatever iron we can get.", completion = "This will do. Throm-ka, {name}.", objectives = "Obtain 200 pieces of Unprocessed Iron Ore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51071] = { id = 51071, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Sabertusk Empress", description = "To any and all brave enough to seek the challenge: \n\nFind and defeat a ferocious Sabertusk Empress, the strongest and most vicious of all sabertusks in Zuldazar. \n\nThey can be found up and down the road from the Village in the Vines. \n\nA reward for any that succeed!", progress = "The wanted poster stands with tasks etched on it.", completion = "Thank you, champion. Dat is one less threat to de area.", objectives = "Slay a Sabertusk Empress", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51072] = { id = 51072, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Prime Thumpknuckle", description = "To any and all brave enough to seek the challenge: \n\nFind and defeat a Prime Thumpknuckle, the largest and most dangerous of all the wild gorillas.\n\nThey can be found up and down the road from the Village in the Vines. \n\nA reward for any that succeed!", completion = "You faced down those Thumpknuckles? Dat is worth a lot to us. Thank you.", objectives = "Slay a Prime Thumpknuckle", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51078] = { id = 51078, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azerite Madness", description = "There be a group of earth elementals nearby that be goin' crazy due te havin' Azerite infused onto 'em.\n\nWe cannot allow this Azerite to spread to any more elementals. We need te put 'em down.\n\nGo and fight these Azerite infused elementals nearby. When they be down, use yer amulet to absorb their lingerin' Azerite.\n\nIt be a shame te do this, but we're fightin' these things in order te save the planet.You will learn:", objectives = "Absorb Azerite from defeated Azerite Infused Elementals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51081] = { id = 51081, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Syrawon the Dominus" }
quests[51082] = { id = 51082, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iron Stores", description = "While the mine is under Horde banners our peons ensure the iron supply never runs dry.\n\nThis key provides access to the chest. Make sure it still works.", progress = "Chest giving you trouble?", completion = "Heh, glad to see it still works.", objectives = "Use the Heavy Iron Key to access the Iron Stores.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51084] = { id = 51084, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Chronicler" }
quests[51085] = { id = 51085, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Dark Chronicler", description = "Champion wanted for an expedition into the depths of Xibala. \n\nStrange noises and wails come from the bones at night and our workers are terrified. \n\nSeek out the source of the strange noises and destroy it, and a reward will be yours.", completion = "The ruins will now be silent at night.", objectives = "Slay Dark Chronicler", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51086] = { id = 51086, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Break's Over", description = "It's come to my attention a few of our peons have been caught sleeping instead of hauling iron from the mine. We can't let our supplies get low.\n\nTake this club and get those lazy peons back on track.", completion = "With our peons back on track the iron stores should be full in no time.", objectives = "Return 3 Lazy Peons to work.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51087] = { id = 51087, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Dark Chronicler", description = "Champion wanted for an expedition into the depths of Xibala. \n\nStrange noises and wails come from the bones at night and our workers are terrified. \n\nSeek out the source of the strange noises and destroy it, and a reward will be yours.", progress = "Something stirs in the ruins. I hope you can discover its source!", completion = "A spirit? How terrible!", objectives = "Slay Dark Chronicler", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51088] = { id = 51088, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heart of Darkness", description = "We sent troops with Captain Conrad ahead to Nazmir to gain a foothold in that hellish jungle.\n\nThe reports we've been receiving of the local troll population are... disconcerting.\n\nThey're in over their heads, {name}. I have Brann Bronzebeard prepped and ready to head out.\n\nAccompany Brann to Nazmir so we can secure our position. The Wind's Redemption is at your disposal.", completion = "I've wrestled with death, {race}. It's the most unexcitin' contest ye can imagine.", objectives = "Accompany Brann to Fort Victory in Nazmir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51089] = { id = 51089, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Tojek", description = "<This appears to be a list of threats in the immediate vicinity, a angry scribble grabs your attention.>\n\nA reward of gold be promised to de one dat slays da creature Tojek. You know what dey say, an eye for an eye! \n\n-Rovash", completion = "Hah! He be dead? Really? Dat be wonderful!\n\nHere be your reward, you earned it!", objectives = "Hunt down Tojek.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51090] = { id = 51090, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Picturesque Norwington Estate" }
quests[51091] = { id = 51091, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Ten'gor and Nol'ixwan", description = "To any hunters worthy of the challenge: \n\nFind and defeat the dueling giant direhorn and devilsaur, named Nol'ixwan and Ten'gor. \n\nTheir never-ending battle has disrupted travel throughout Zuldazar. \n\nGlory for any that succeed!", progress = "Do you think you are de greatest hunter in all of Zandalar?", completion = "Those two have been fighting for supremacy as long as can be remembered. They will not be bothering de jungles of Zandalar anymore.", objectives = "Slay Nol'ixwan and Ten'gor", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
