quests[51101] = { id = 51101, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wounded King", description = "I have things under control here... for now, at any rate.\n\nIf we want to salvage this situation, Rastakhan must survive. Habutu is gone, but his other guardian, Zolani, has sent word.\n\nShe is protecting the King at a small fishing village called Zeb'ahari. Find Zolani and do what you can to ensure Rastakhan lives.\n\nBe careful, {name}.", completion = "It is good dat you have come. De king is dying, and we do not have much time to change dat.", objectives = "Meet Zolani in Zeb'ahari.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
