quests[51111] = { id = 51111, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "King or Prey", description = "My loa has seen fit to question my resolve.\n\nFor my people, my pride, and my faith, we will correct dis. Return to your Horde. Ready your forces, and I will ready mine.\n\nWhen de time comes, we will strike back against de traitorous snake, Zul.", completion = "You have gone beyond our wildest expectations!\n\nThank you, {name}, for upholding the honor of the Horde. We must remember who we were, to realize what we may become.", objectives = "Return to Baine in the Royal Chambers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
