quests[51129] = { id = 51129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dubious Offering", description = "Cannae be sure o' the wisdom o' this Captain Conrad.\n\nSendin' our own on these blood troll bats with offerin's?\n\nSomethin' about this stinks more'n an armpit after a bar fight.", completion = "I wasn't built for fallin' that far! The only part o' me that doesn't hurt is me hat!", objectives = "Take a bat from Fort Victory to Zalamar in Nazmir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51130] = { id = 51130, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azerite for the Horde!" }
quests[51131] = { id = 51131, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Absolutely Barbaric" }
quests[51134] = { id = 51134, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If Bones Could Talk", description = "<These skeletons appear to be rising out of the ancient ruins that dot the land here. Their bones are covered with what looks like runes, but time has worn away all but fragments of the markings.\n\nIf you could find some of these runes intact, Lucille might be able to decipher them to find out where these skeletons come from...\n\n...and why they are no longer at rest.>", progress = "What's this?", completion = "These markings... this is the language of the Drust!\n\nThe magic of the coven must be disturbing their spirits, drawing them back into our world to fight us once more!\n\nThis is unsettling... but it is another reason we must bring an end to the Heartsbane!", objectives = "Collect a Pristine Rune-Etched Bone from Awakened Dead in Alpine Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51139] = { id = 51139, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Tojek", description = "<The tattered paper appears to include a list of known threats in the area.\n\nThe top of the list reads: \"Tojek - Direhorn - Responsible for damages to 3 vehicles, 6 supply crates, and the tragic loss of Garrick Blacksteel's mole machine, avoid at all costs.\"\n\nPerhaps you can hunt down this creature to prevent further attacks.>", completion = "Ye got rid o' that blasted direhorn? Fantastic! Maybe some day I can get tae work on rebuilding me machine now!\n\nThank ye!", objectives = "Hunt down Tojek.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51140] = { id = 51140, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Share the Wealth", description = "<Though old and mud covered, this is still gold, lots of it! It's not enough to be Nedly's legendary lost treasure, but it's still several thousand in gold coins.\n\nIt's a significant find, and should be returned to Shealds to be split among all the workers.>", completion = "Some people would have just run off with this, but you didn't! We'll split this up into two hundred and fourteen shares. Here's your cut.", objectives = "Take the gold to Shealds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51142] = { id = 51142, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pests", description = "Confound it all! These rat-faced thieves keep getting into all of our supplies! I swear, anything that's not tied down, and even some things that are, they nip off with'.\n\nYou want to make a difference for the war effort in Zandalar? Pop off as many of those buggers as you can find. \n\nOtherwise, get on with it!", completion = "A thief has come to steal from thieves?", objectives = "Slay 8 Thieving Snappers in the Alliance Docks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51144] = { id = 51144, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bundle of Furs", description = "You there! Would you happen to be passing by Hatherford?\n\nI have a delivery to make there, but my normal delivery person fell ill after a trip to Anglepoint. \n\nWould you mind taking this bundle of furs to Dandy Jones in Hatherford for me? I would go myself, but I must hold down my stall.", progress = "Welcome to my inn, friend! How can  I help ya?", completion = "Ah, my furs! Thanks for the delivery. It's getting a bit cold out here - these will be perfect for the beds!\n\nIf you need food or a place to lay your head, I can offer you the best!", objectives = "Deliver the Bundle of Warm Furs to Dandy Jones in Hatherford.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51145] = { id = 51145, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Curse of Jani", description = "Thief and killer, know dat ya be standin' before da Patron of Scavengers, da Lord of Thieves, da God of Garbage, Master of Minions, and da Keeper of Secrets.\n\nYa be standin' before me in raiment worth entire kingdoms of gold, bearin' weapons dat cost more than even me most devout and renowned followers will ever earn.\n\nI tink now be a good time ta teach ya a lesson. Maybe show ya high and mighty greatness what it means ta be snappin' in da gutters.", progress = "You be bitin' that ratmon yet?", completion = "Haha! Well done, wealthy stranger. When ya out and about in dese lands, keep ya eyes open. Ya never know when one of de children might be pointin' ya ta a useful place.", objectives = "Survive the Trial of Jani.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51146] = { id = 51146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kua'fon's Day Off", description = "You know, I think Kua'fon might be lonely when you are not here.\n\nWhat makes me say that? Well, I got a very angry scroll from a Tortollan indicating he was stealing shiny things from their stalls, but that could mean anything.\n\nYou should probably stop him before he damages your reputation, hm?\n\n<Wingminder Goja cackles.>", completion = "<Kua'fon apologetically headbutts you.>\n\nSkree.", objectives = "Stop Kua'fon from being a nuisance in the Port of Zandalar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51147] = { id = 51147, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kua'fon's Day Off", description = "A messenger came from de Terrace of de Chosen. Your companion is at it again.\n\n<Wingminder Goja chuckles.>\n\nNot even de priests of Pa'ku seem to be able to convince him to leave. You should go and send him back home, where he belongs.", completion = "<Kua'fon scrapes his rough tongue over your cheek.>\n\nSkree.", objectives = "Find Kua'fon at the Terrace of the Chosen and send him home.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51149] = { id = 51149, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Left at the Port", description = "There was a mishap when we were loading the most recent shipment for the Southwind Station. Apparently some paperwork meant for the dockmaster was left behind.\n\nHe can't hand over deliveries to the couriers without it, but the next cargo ferry won't be departing any time soon. Do you think you could deliver it by foot? The ferry dock is just a short ride down the road.", completion = "I was wondering where this was. Thank you kindly.", objectives = "Deliver the package to Dockmaster Tyndall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51150] = { id = 51150, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honoring the Fallen", description = "This is a shameful situation. Unforgivable! The soldiers weren't carryin' offerrin's to the blood trolls, they WERE the offerin'!\n\nIt'd be right difficult to bury 'em proper in this hole. Best we can do is get their dog tags.\n\nPoor lads an' lassies.", completion = "I'll keep these tags an' get 'em to their families. Let's keep mum on the manner o' their deaths, aye? No need to cause 'em even more sadness.", objectives = "Recover 7 Dog Tags from Fort Victory soldiers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51151] = { id = 51151, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Letter to the League", description = "A researcher at the Resort up the hill was hoping to get a letter out to a group called the \"Explorers' League\". He claims that they have a camp set up near some old Drust ruins on the other side of the sound.\n\nThere's no official station so it will have to be delivered by hand. If you happen to head in that direction, can you take it with you?", completion = "We might have a wee problem on our hands.", objectives = "Find the Explorers' League members at the Thovas Base-Camp.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51153] = { id = 51153, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mor'fani the Exile" }
quests[51154] = { id = 51154, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Past Due" }
quests[51155] = { id = 51155, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brgl-Lrgl the Basher" }
quests[51156] = { id = 51156, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fangcaller Xorreth" }
quests[51157] = { id = 51157, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Golanar" }
quests[51159] = { id = 51159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring out the Big Gun", description = "<The cannon here is still in good condition. It's a lot of firepower to slow down the Horde.\n\nTaking this to Lea Martinel at Eckhart Lodge would really help their defenses.>", completion = "This is an unexpected surprise!", objectives = "Cannon delivered.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51161] = { id = 51161, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Za'roco", description = "To any with honor and a sharp blade: \n\nFind and kill the thief, Za'roco. \n\nThose that betray their fellow exile don't deserve to live. \n\nAny who can cross his name off this list will earn a fitting reward.", completion = "Za'roco got what he deserved, and now, so will you.", objectives = "Find and kill Za'roco the Grifter.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51162] = { id = 51162, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Taz'raka the Traitor", description = "To all caravans and travelers:\n\nBeware Taz'raka the Traitor, a skeleton ambushing travelers on the road near Port of Zem'lan. If you must travel on that road, move quickly, and avoid entering any of the ruins.\n\nSeveral caravans have combined resources to offer a reward for Taz'raka's death.\n\nTo collect, speak with Norah in Camp Lastwind.", progress = "Be careful out there, {name}.", completion = "A bounty worth paying. Thank you, {name}.", objectives = "Find and kill Taz'raka the Traitor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51164] = { id = 51164, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Cobra Excursion Participants", description = "Attention guests of the Goldtusk Inn:\n\nWe're proud to announce a surprise new addition to our lineup of excursion activities!\n\nThe new Giant Deadly Unstoppable Killer Cobra Experience is now available!\n\nThere's no need to sign up, you've all been automatically volunteered for this activity.\n\nTo participate, simply travel into the dunes north of the inn and try not to be killed by the massive cobra now patrolling the area.\n\nWe are not currently offering guided tours for this activity. Have fun!", progress = "All of our excursion survivors receive a reward!", completion = "You killed de giant snake? Congratulations!\n\nGuess I'd better update the brochure excursion list.", objectives = "Kill Sevriss.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51165] = { id = 51165, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Sandscout Vesarik", description = "To any and all who wish to see the Faithless empire fall: \n\nSandscout Vesarik was spotted patrolling the dunes to the east. Gather a formidable force and strike him down!\n\nThose who succeed will be granted a fitting reward.", progress = "Sandscout Vesarik was last seen patrolling the dunes to the east.", completion = "Vesarik's death will be a devastating blow to the Faithless forces.", objectives = "Find and kill Sandscout Vesarik.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51166] = { id = 51166, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down to the Roots" }
quests[51167] = { id = 51167, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood of Hir'eek", description = "Spooky chantin' in the next room can only mean one thing: someone's askin' for the ol' what-fer!\n\nI'd give ya a hand but I gotta drink a couple-a potions before I'm back on me feet.\n\nTake out that blood witch and I bet the magic'll dissipate.", progress = "Two things I can't abide in this world: witches an' tall chairs.", completion = "Always thought witches dinnae wear clothes when ritualisin'. And where was 'er broomstick?", objectives = "Defeat Blood Witch Pakkala.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51168] = { id = 51168, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zealots of Zalamar", description = "We're surrounded by the enemy, {name}, and it's got me blood ragin'!\n\nI'm fit as a fi... instrument... and ready to help get us outta this forsaken cavern.\n\nLet's show 'em the end o' their miserable lives, eh?", progress = "Smells like... Victory.", completion = "Worst places in the world are all dark holes with no artifacts about!", objectives = "Slay 10 Zalamar Zealots in The Fall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51169] = { id = 51169, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flight from the Fall", description = "Let's get outta this hole! Hairs on the back o' me neck won't settle down. Was hopin' I'd find some artifacts, or treasures, or haggis, or at least a few worthwhile trinkets down here.\n\nThose bats look like the ones that we came on... hopefully they'll take us back to Fort Victory and not some rotten grotto with no valuables inside.", completion = "Fort Victory's got the wrong name. Somethin' like Fort Folly seems more appropriate ta me.", objectives = "Take a bat to Fort Victory.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51170] = { id = 51170, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ooh Rah!", description = "We're going to need a harbor for our base of operations. Those ruins across the way should be perfect for our needs.\n\nUnfortunately, it looks to be occupied by a hostile force so I'm sending the marines to secure the shore. As the most experienced soldier here I want you to go with them. \n\nI don't want to see a single hostile remain when our engineers arrive.\n\nNow, go take that harbor in the name of the Alliance!", completion = "Thank the Light you came with us! Private Leonard didn't make it and Private James got captured by those damn snake-men! \n\nThe important thing is I think the rest of 'em got scared off once you started raining death down on 'em.\n\nSmall victories, right?", objectives = "Capture Shatterstone Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51172] = { id = 51172, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forked Lightning" }
quests[51173] = { id = 51173, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sandfishing" }
quests[51174] = { id = 51174, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Instructions Not Included" }
quests[51175] = { id = 51175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azerite Wounds" }
quests[51176] = { id = 51176, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unaccounted For" }
quests[51177] = { id = 51177, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lessons of the Damned", description = "When I arrived here in disguise, the blood trolls thought me some sort of messenger of their Blood God.\n\nI seized the advantage and played into their primitive beliefs.\n\nI came here intending to open trade and learn how we can work with them against the Horde.\n\nWhat I discovered was altogether more compelling. I will show you.", completion = "Dreadful business, {name}. I was set on a rescue or corpse recovery. To see one o' our own that far gone was... unsettlin'.\n\nWhat's done is done. I'll send a report back to Halford. Don't bother yerself with the busy work this time.", objectives = "Learn of Captain Conrad's progress.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51178] = { id = 51178, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hundred Troll Holdout" }
quests[51179] = { id = 51179, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azerite Madness" }
