quests[51185] = { id = 51185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azerite Empowerment" }
quests[51190] = { id = 51190, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Granting a Reprieve", description = "Now, on to more pressing matters.\n\nThe Forsaken have shown up and are preventing us from saving our people. All my soldiers are either injured, exhausted, or in no shape for fighting.\n\nIt seems these trollish natives have joined them as well. I am spread too thin.\n\nKill the Horde. Kill the Zandalari. Kill them all.", completion = "A few less cretins to worry about.", objectives = "Slay 8 Forsaken and 8 Zandalari in Talanji's Rebuke.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51191] = { id = 51191, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Save Them All", description = "Reinforcements? Ah thank tha Light!\n\nWe done the best we can triaging the injured, but we need help. We need more hands that can heal wounds or at the verra least apply bandages.\n\nHow are yer hands? Here, take these bandages and do what ye can tae treat tha injured.", progress = "We've done what we can. Now all we can do is rest.", completion = "Ye'd make an excellent medic. Or at tha verra least a good nurse.", objectives = "Heal 8 injured sailors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51192] = { id = 51192, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lack of Surplus", description = "Food, wood, cloth... we're short on everything. Of course, I'm always short, but that donna stop me.\n\nHeh.\n\nSee what ya can salvage from tha shipwrecks.", progress = "Did ya find anything useful?", completion = "It's amazin' what we can do when we have tha supplies tae do it!", objectives = "Collect supplies from the shipwreck.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51193] = { id = 51193, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That One's Mine", description = "Yer here to help? I donna have anything... Well, maybe I do.\n\nI know it's just a simple hammer. I know it's not special. But it's mine.\n\nThat disgustin undead, Alan Hawkins, is taunting me wi'it. I promised Feorea I wouldna run off tae fight him, but ye made no such promises.\n\nKill him and retrieve me hammer.", progress = "Donna judge me. This is me best hammer.", completion = "I know it doesna seem like a special hammer. But to me, it's verra important.", objectives = "Retrieve Degdod's Hammer from Alan Hawkins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51198] = { id = 51198, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fertilizer Duty" }
quests[51199] = { id = 51199, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Glory of the Hunt", description = "You here for the festival, friend?\n\nWe're still settin' up here, but the hunt should've started by now!\n\nIf ya want to take part, go meet Abbey in Foxhollow Woods. She'll get you all set up.\n\nHappy huntin'!", completion = "Ah, Gora sent you! Care to join in the hunt?", objectives = "Meet Abbey Watkins at the edge of Foxhollow Woods.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51200] = { id = 51200, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Black Sheep", description = "I'll admit, Millie has never really been one to follow the herd. Usually, it's no problem. She'll wander off for a bit, do her own thing and eventually make her way back to the flock.\n\nThe hills have grown increasingly more dangerous lately, especially with the wolves and giants about. She's been gone awhile and I'm starting to worry.\n\nCould you please help me look for her?", completion = "Oh, my sweet Millie! Thank you, {name}. I'm in your debt.", objectives = "Find and rescue Millie.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51201] = { id = 51201, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Troll's Tale", description = "You've arrived at an... interesting time, {class}. All of my ships have been destroyed. Half of my men are feeding the fishes, and the rest aren't doing much better. We're as good as doomed.\n\nAnd still, the Alliance prevails.\n\nThese Zandalari trolls are to blame for this carnage. I need to know how they did it before we kill them all and escape from this Light-forsaken island.", progress = "<Thom sneers at the Zandalari troll kneeling before him.>\n\nTalk, you filthy brute!", completion = "Princess... Talanji, you say? I see.\n\nKing Wrynn will be told about this. This Zandalari princess will learn what it means to make an enemy of the Alliance.", objectives = "Speak with the Captured Zandalari Troll to find out how the Alliance fleet was sunk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51203] = { id = 51203, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cry Wolf", description = "Lately, the wolves have been terrorizing my flock. They weren't an issue until the giants moved in and pushed them out of their normal hunting grounds.\n\nI feel bad asking you to do this, but could you thin their ranks a bit? If there are fewer wolves competing for food, maybe they'll leave us alone.", completion = "My flock should be able to rest easier now.", objectives = "Kill 10 Feral Razorclaws.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51204] = { id = 51204, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Razorclaw Alpha", description = "Adventurers Needed!\n\nThe wolves have been attacking my flock! I don't have the means to fight them back.\n\nI've seen one, much larger than the rest, leading a few of the attacks.\n\nPlease, if anyone can help, I'll gladly offer whatever reward I can muster.\n\n- Shepherd Mary Ann Milbrooke", completion = "Wow, I wasn't sure if anyone would ever answer my posting. Thank you!", objectives = "Slay the Razorclaw Alpha.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51205] = { id = 51205, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aww, Rats!", description = "I didn't sign up for this! I just want to get back to the simple things, like grinding wheat and drinking mead.\n\nAs if things couldn't get any worse around here, there's an army of rats ransacking the shed and I don't have the stomach to exterminate them.\n\nHere, I got this off some crazy gnome that stopped into port recently. I thought maybe it'd help with the bees. Maybe you can try it on the rats?", completion = "Thank you so much. I'll get rid of these little guys.", objectives = "Collect 8 Bilge Rats.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51207] = { id = 51207, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ettin It Done", description = "Okay, now here's a little something I whipped up for you with those extra ingredients.\n\nWe don't have much around here in the way of weapons, but we've got gunpowder and plenty of flour. A surprisingly explosive combination!\n\nToss one of these goodies at those nasty ettins, should disorient them long enough to give 'em a good whack upside the head!\n\nYou thought I was just a sweet old lady, baking delicious cookies for any ol' passerby? Hah, I'll have you know I was quite the firecracker in my day.", completion = "{name}, my grandson could learn a thing or two from you. Come back to visit anytime!", objectives = "Use Flour Bombs to slay 8 Ettins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51208] = { id = 51208, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wheat A Minute", description = "With the storage shed ransacked by rats and the giants pillaging our shipments, we've been running low on food.\n\nWhen I was making my way out here, I saw a bunch of grain sacks littered about, near the wrecked wagons.\n\nI'd appreciate it if you could retrieve whatever you find while you're out here.", completion = "Wow! I can't believe you were able to carry all of that.", objectives = "Collect 10 Grain Sacks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51209] = { id = 51209, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mighty Grokkfist", completion = "I can't believe it actually worked. I thought for sure we'd all be squished!", objectives = "Use the Pack of Rats to kill Grokkfist.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51210] = { id = 51210, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blast Back the Siege" }
quests[51211] = { id = 51211, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Heart of Azeroth", description = "Our world's dyin', {name}. Sargeras's sword has cut deep. Her pain is drivin' the elements into a frenzy!\n\nI can hear Azeroth's voice, but she needs more than her speaker.\n\nShe needs her champion.\n\nFar below us lies an ancient titan vault called the Chamber of Heart. I sense she wishes tae speak tae ye there.\n\nCome with me into the chamber. It may be our only chance tae save her!", progress = "Ye need tae hear from Azeroth herself, {name}.", completion = "The Heart of Azeroth... that's the key tae healin' her wounds!", objectives = "Travel to the Chamber of Heart and commune with Azeroth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51212] = { id = 51212, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waycrest Manor: Witchy Kitchen" }
quests[51213] = { id = 51213, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waycrest Manor: No need to Hag-gle" }
quests[51214] = { id = 51214, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Be A Dear", description = "As you can plainly see by the rocks falling from the sky, we are under siege by those terrible ettins!\n\nIf you could be obliged to lend us a hand, I'd be most grateful. We can't possibly hope to defeat them unless we properly prepare you first.\n\nCould you be a dear and fetch a few things for me from around the Hamlet? Some water, a sack of flour, and a bundle of logs should help.\n\nI've already sent my grandson, Charles, off to fetch a few other items. I've not seen him for quite a while though.", progress = "Did you have any trouble dear?", completion = "Thank you so much. I wish Charles was half as studious as you.", objectives = "Collect a Water Bucket, Sack of Flour, and Logs, then return them to Marie Davenport.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
